var i=`0513-dolma-iraqi-style`;var n=`world-0513`;var a=`IQ`;var o=`western-asia`;var r=4;var l=97;var g={en:`Dolma Iraqi Style`,ua:`Долма по-іракськи`};var s={en:`A traditional dish from Iraq, centered on grape leaves, white rice, ground lamb, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірак. Основні складники: виноградне листя, білий рис, фарш з ягнятини, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Separate and blanch the leaves in hot water for about 8 minutes until pliable. Drain and trim thick ribs.`,ua:`Відокремте й бланшуйте листя в гарячій воді приблизно 8 хвилин до гнучкості. Обсушіть і зріжте товсті прожилки.`,t:[`blanching`],m:8,i:[[`grape-leaves`,45,`pcs`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`white-rice`,320,`g`],[`ground-lamb`,400,`g`],[`yellow-onion`,170,`g`],[`parsley`,45,`g`],[`tomato`,220,`g`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:17,i:[[`eggplant`,330,`g`],[`red-bell-pepper`,250,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 60 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 60 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:60,i:[[`chicken-stock`,850,`ml`],[`lemon-juice`,45,`ml`]]}];var h={slug:i,id:n,country:`IQ`,region:o,servings:4,minutes:97,title:g,text:s,steps:m};export{a as country,h as default,n as id,l as minutes,o as region,r as servings,i as slug,m as steps,s as text,g as title};